import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import username from 'flarum/common/helpers/username';
import { t } from '../util';
/** One request per creator per visit, however many of their works are opened. */
const asked = new Map();

/**
 * A strip of the creator's other works with pictures. One request, made once
 * the card is drawn, for the creator's six newest discussions; works without
 * a picture are left out of the strip.
 */
export default class MoreFrom extends Component {
  works = null;
  oncreate(vnode) {
    super.oncreate(vnode);
    const user = this.attrs.discussion.user();
    if (!user) return;
    const key = String(user.id());
    if (!asked.has(key)) {
      asked.set(key, app.store.find('discussions', {
        filter: {
          author: user.username()
        },
        page: {
          limit: 7
        },
        include: 'user'
      }, undefined, {
        errorHandler: () => {}
      }).then(list => [...list]).catch(() => []));
    }
    asked.get(key).then(list => {
      this.works = list;
      m.redraw();
    });
  }
  view() {
    const current = this.attrs.discussion;
    const user = current.user();
    const works = (this.works || []).filter(d => d !== current && d.attribute('studioCover')).slice(0, 6);
    if (!user || !works.length) return m("div", {
      className: "StudioMore StudioMore--empty"
    });
    return m("div", {
      className: "StudioMore"
    }, m("h2", {
      className: "StudioMore-title"
    }, t('more.title', {
      name: username(user)
    })), m("ul", {
      className: "StudioMore-grid"
    }, works.map(work => m("li", null, m(Link, {
      href: app.route.discussion(work),
      className: "StudioMore-item",
      title: work.title()
    }, m("img", {
      src: work.attribute('studioCover'),
      alt: work.title(),
      loading: "lazy",
      decoding: "async"
    }))))));
  }
}
flarum.reg.add('ernestdefoe-studio', 'forum/work/MoreFrom', MoreFrom);