import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import classList from 'flarum/common/utils/classList';
import { bump, t } from '../util';
/**
 * The opening post's pictures: one large, the rest as thumbnails beside it
 * (under it on a phone, as dots).
 *
 * The stage keeps one box for every picture, the first picture's shape, and
 * fits each inside it: stepping through them never moves the words below.
 */
export default class Stage extends Component {
  index = 0;
  view() {
    const pictures = this.attrs.pictures;
    const count = pictures.length;
    const index = Math.min(this.index, count - 1);
    const current = pictures[index];
    const ratio = Math.max(420, Math.min(1300, pictures[0].ratio || this.attrs.ratio || 750));
    return m("div", {
      className: classList('StudioStage', {
        'StudioStage--single': count === 1
      })
    }, count > 1 ? m("div", {
      className: "StudioStage-thumbs",
      role: "group",
      "aria-label": t('stage.thumbnails')
    }, pictures.map((picture, i) => m("button", {
      type: "button",
      className: classList('StudioStage-thumb', {
        active: i === index
      }),
      "aria-label": t('stage.show', {
        number: i + 1,
        count
      }),
      "aria-pressed": i === index ? 'true' : 'false',
      onclick: () => {
        this.index = i;
        bump();
      }
    }, m("img", {
      src: picture.thumb,
      alt: "",
      loading: "lazy",
      decoding: "async"
    })))) : null, m("figure", {
      className: "StudioStage-figure",
      style: {
        aspectRatio: `1000 / ${ratio}`
      },
      tabindex: count > 1 ? 0 : undefined,
      "aria-label": count > 1 ? t('stage.label', {
        number: index + 1,
        count
      }) : undefined,
      onkeydown: e => {
        if (e.key === 'ArrowRight') {
          this.step(1);
          e.preventDefault();
        } else if (e.key === 'ArrowLeft') {
          this.step(-1);
          e.preventDefault();
        }
      }
    }, m("a", {
      href: current.src,
      target: "_blank",
      rel: "noopener noreferrer",
      className: "StudioStage-open"
    }, m("img", {
      key: current.src,
      src: current.src,
      alt: current.alt,
      decoding: "async",
      fetchpriority: index === 0 ? 'high' : undefined
    })), count > 1 ? m('[', null, m(Button, {
      className: "Button Button--icon StudioStage-step StudioStage-step--prev",
      icon: "fas fa-chevron-left",
      "aria-label": t('stage.previous'),
      onclick: () => this.step(-1)
    }), m(Button, {
      className: "Button Button--icon StudioStage-step StudioStage-step--next",
      icon: "fas fa-chevron-right",
      "aria-label": t('stage.next'),
      onclick: () => this.step(1)
    }), m("span", {
      className: "StudioStage-counter",
      "aria-hidden": "true"
    }, index + 1, " / ", count), m("span", {
      className: "StudioStage-dots",
      "aria-hidden": "true"
    }, pictures.map((_, i) => m("span", {
      className: classList('StudioStage-dot', {
        active: i === index
      })
    })))) : null));
  }
  step(by) {
    const count = this.attrs.pictures.length;
    this.index = (this.index + by + count) % count;
    bump();
  }
}
flarum.reg.add('ernestdefoe-studio', 'forum/work/Stage', Stage);