import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import Avatar from 'flarum/common/components/Avatar';
import Icon from 'flarum/common/components/Icon';
import listItems from 'flarum/common/helpers/listItems';
import classList from 'flarum/common/utils/classList';
import username from 'flarum/common/helpers/username';
import { boxRatio, flagOf, mediumOf, nearFor, t } from '../util';
/**
 * One discussion in the gallery: its own first picture in a box of the
 * picture's shape (so nothing moves as it loads), the creator's avatar
 * overlapping it, the title, and replies.
 *
 * A discussion without a picture is a typographic card: its title set large
 * on its medium's colour.
 */
export default class Card extends Component {
  view() {
    const discussion = this.attrs.discussion;
    const cover = discussion.attribute('studioCover');
    const href = app.route.discussion(discussion, nearFor(discussion));
    const user = discussion.user();
    const medium = mediumOf(discussion);
    const flag = flagOf(discussion);
    const count = discussion.attribute('studioImages') || 0;
    const tint = medium?.color() || null;
    return m("article", {
      className: classList('StudioCard', {
        'StudioCard--type': !cover,
        'StudioCard--tile': this.attrs.tile,
        'is-unread': discussion.isUnread(),
        'is-sticky': discussion.attribute('isSticky')
      }),
      style: tint ? {
        '--studio-tint': tint
      } : undefined
    }, m(Link, {
      href: href,
      className: "StudioCard-media",
      tabindex: "-1",
      "aria-hidden": "true"
    }, cover ? m("span", {
      className: "StudioCard-box",
      style: {
        aspectRatio: `1000 / ${boxRatio(discussion.attribute('studioRatio'))}`
      }
    }, m("img", {
      src: cover,
      alt: "",
      loading: "lazy",
      decoding: "async"
    })) : m("span", {
      className: "StudioCard-box StudioCard-box--type"
    }, m("span", {
      className: "StudioCard-typeTitle"
    }, discussion.title())), flag ? m("span", {
      className: "StudioCard-flag"
    }, flag.name()) : null, count > 1 ? m("span", {
      className: "StudioCard-count",
      title: t('card.pictures', {
        count
      })
    }, m(Icon, {
      name: "far fa-images"
    }), " ", count) : null), m("div", {
      className: "StudioCard-meta"
    }, m("div", {
      className: "StudioCard-who"
    }, user ? m(Link, {
      href: app.route.user(user),
      className: "StudioCard-avatar",
      "aria-label": user.displayName()
    }, m(Avatar, {
      user: user
    })) : m("span", {
      className: "StudioCard-avatar"
    }, m(Avatar, {
      user: null
    })), m("span", {
      className: "StudioCard-name"
    }, username(user)), medium && !this.attrs.tile ? m("span", {
      className: "StudioCard-medium"
    }, medium.name()) : null), m("h3", {
      className: "StudioCard-title"
    }, m(Link, {
      href: href
    }, discussion.title())), this.statsView()));
  }
  statsView() {
    const discussion = this.attrs.discussion;
    const items = [];
    const badges = discussion.badges().toArray();
    if (badges.length) {
      items.push(m("ul", {
        className: "StudioCard-badges"
      }, listItems(badges)));
    }
    if (app.forum.attribute('studioCounts')) {
      const replies = Math.max(0, (discussion.commentCount() || 1) - 1);
      const views = discussion.attribute('views');
      items.push(m("span", {
        className: "StudioCard-stat"
      }, t('card.replies', {
        count: replies
      })));
      if (typeof views === 'number') {
        items.push(m("span", {
          className: "StudioCard-stat"
        }, t('card.views', {
          count: views
        })));
      }
    }
    if (discussion.isUnread()) {
      items.push(m("span", {
        className: "StudioCard-unread"
      }, t('card.new')));
    }
    return items.length ? m("div", {
      className: "StudioCard-stats"
    }, items) : null;
  }
}
flarum.reg.add('ernestdefoe-studio', 'forum/gallery/Card', Card);